// Sign /api/processing/stage call with stage='failed' so the brand row's
// onboarding_status flips to 'failed'. This is what makes the red Retry
// banner appear on /[slug]/processing — without it, the page only shows
// the soft-timeout retry after 10 minutes, which resets every navigation.
const crypto = require('crypto');
const brand_id = $json.brand_id;
if (!brand_id) {
  // Failure happened before brand_id was extracted — skip the DB write.
  return { json: { ...$json, _stage_skip: true } };
}
const body = JSON.stringify({ brand_id, stage: 'failed' });
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887').update(body).digest('hex');
return { json: { ...$json,
  _stage_url: 'https://vagrancy-pupil-spiritism.ngrok-free.dev/api/processing/stage',
  _stage_body: body,
  _stage_headers: {
    'content-type': 'application/json',
    'x-n8n-signature': sig,
    'x-n8n-request-id': reqId,
    'x-n8n-timestamp': ts,
  },
}};

// Build HMAC-signed S03 alert — fires on any unhandled A03 error.
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const e = $json;

let brand_id = null;
try { brand_id = $('Verify HMAC + parse').first().json.brand_id ?? null; } catch (_) {}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const makeUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

const body = JSON.stringify({
  anomaly_id:   makeUUID(),
  anomaly_type: 'n8n_failure',
  severity:     'error',
  source_flow:  'N8N-A03',
  brand_id,
  message:      e.execution?.error?.message || 'A03 onboarding flow failed',
  details: {
    failed_node:  e.execution?.lastNodeExecuted ?? null,
    error_name:   e.execution?.error?.name      ?? null,
    execution_id: e.execution?.id               ?? null,
  },
  timestamp: new Date().toISOString(),
});

const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');
return {
  _body: body,
  _headers: {
    'content-type':     'application/json',
    'x-n8n-signature':  sig,
    'x-n8n-request-id': `${$execution.id}-err-a03`,
    'x-n8n-timestamp':  new Date().toISOString(),
  },
};

// Verify HMAC + parse. Hard Rule #5 — n8n is just routing; we trust the
// inbound signature from /lib/n8n-outbound.ts. HARDCODED secret + base URL
// for paste-and-run import.
const WEBHOOK_SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887'; // ⚠️ HARDCODED SECRET
const APP_BASE_URL = 'https://vagrancy-pupil-spiritism.ngrok-free.dev'; // ⚠️ HARDCODED ngrok URL
const crypto = require('crypto');
const headers = $input.first().json.headers || {};
const given = headers['x-n8n-signature'];
const ts    = headers['x-n8n-timestamp'];
const rid   = headers['x-n8n-request-id'];
if (!given || !ts || !rid) throw new Error('Missing required HMAC headers');
const drift = Math.abs(Date.now() - Date.parse(ts));
if (drift > 5 * 60 * 1000) throw new Error(`Timestamp drift ${drift}ms > 5 min`);
const rawBody = JSON.stringify($input.first().json.body);
const expected = crypto.createHmac('sha256', WEBHOOK_SECRET).update(rawBody).digest('hex');
if (expected !== given) throw new Error('HMAC signature mismatch');
const body = $input.first().json.body || {};
if (!body.brand_id || !body.slug) throw new Error('brand_id and slug are required');
return { json: {
  brand_id:         body.brand_id,
  slug:             body.slug,
  instagram_handle: body.instagram_handle || null,
  website_url:      body.website_url || null,
  place_search:     body.place_search || { name: '', city: '' },
  form_payload:     body.form_payload || {},
  request_id:       rid,
  _secret:          WEBHOOK_SECRET,
  _base:            APP_BASE_URL,
}};

// GAP 5 fix — emit stage='form_submitted' BEFORE work, not after.
// Live UI shows pipeline transitions accurately.
const crypto = require('crypto');
const d = $('Verify HMAC + parse').first().json;
const body = JSON.stringify({ brand_id: d.brand_id, stage: 'form_submitted' });
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', d._secret).update(body).digest('hex');
return { json: { ...d, _stage_url: d._base + '/api/processing/stage', _stage_body: body, _stage_headers: {
  'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts
}}};

// Build the body for the CEO classify call.
// Reads form_payload.review for critical fields + occasion_flags from top-level payload.
const d = $('Verify HMAC + parse').first().json;
const review = (d.form_payload && d.form_payload.review) || {};
const nonEmpty = (v) => v != null && v !== '' && !(Array.isArray(v) && v.length === 0);
const critical = {
  arabic_dialect:           nonEmpty(review.arabic_dialect),
  brand_differentiator:     nonEmpty(review.brand_differentiator) && String(review.brand_differentiator).trim().length >= 20,
  price_position:           nonEmpty(review.price_position),
  primary_channel:          nonEmpty(review.primary_channel),
  primary_kpi_type:         nonEmpty(review.primary_kpi_type),
  religious_sensitivity:    nonEmpty(review.religious_sensitivity),
  bilingual_ratio:          nonEmpty(review.bilingual_ratio),
  formality_level:          nonEmpty(review.formality_level),
  humor_tolerance:          nonEmpty(review.humor_tolerance),
  tone_anti_attribute_ids:  Array.isArray(review.tone_anti_attribute_ids) && review.tone_anti_attribute_ids.length > 0,
  ramadan_relevance:        nonEmpty(review.ramadan_relevance),
  intent_state:             nonEmpty(review.intent_state),
};
const providedCount = Object.values(critical).filter(Boolean).length;
// Read occasion_flags from top-level payload (passed by submitFinal from form occasions_ranked)
const occasionFlags = Array.isArray(d.occasion_flags) && d.occasion_flags.length > 0 ? d.occasion_flags : ['none'];
return { json: {
  ...d,
  body: {
    flow_id: 'N8N-A03',
    brand_id: d.brand_id,
    payload: {
      request_type: 'onboarding_new',
      trigger_payload: {
        slug: d.slug,
        has_instagram: !!d.instagram_handle,
        has_website: !!d.website_url,
        intake_form_complete: providedCount >= 11,
        critical_fields_provided_count: providedCount,
        critical_fields_provided: critical,
      },
      occasion_flags: occasionFlags,
      current_month_spend_usd: 0,
      monthly_ceiling_usd: 50,
    },
  },
}};

// Sign the CEO classify body.
const crypto = require('crypto');
const d = $json;
const body = JSON.stringify(d.body);
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', d._secret).update(body).digest('hex');
return { json: { ...d, _ceo_url: d._base + '/api/agents/ceo/classify', _ceo_body: body, _ceo_headers: {
  'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts
}}};

// Parse CEO result. confidence_mode === 'Blocked' short-circuits.
const ceoResp = $input.first().json;
const decision = ceoResp.result?.decision || ceoResp.decision || {};
const blocked = decision.confidence_mode === 'Blocked';
return { json: {
  blocked,
  decision,
  ...$('Verify HMAC + parse').first().json,
}};

// GAP 5 — emit stage=ceo_classified BEFORE the IF branch so the live UI
// shows the step transition immediately.
const crypto = require('crypto');
const d = $json;
const body = JSON.stringify({ brand_id: d.brand_id, stage: 'ceo_classified', metadata: { confidence_mode: d.decision?.confidence_mode ?? null }});
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', d._secret).update(body).digest('hex');
return { json: { ...d, _stage_url: d._base + '/api/processing/stage', _stage_body: body, _stage_headers: {
  'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts
}}};

// Emit stage=blocked so UI shows blocked state immediately.
const crypto = require('crypto');
const d = $('Verify HMAC + parse').first().json;
const decision = $('Parse CEO result').first().json.decision || {};
const body = JSON.stringify({
  brand_id: d.brand_id,
  stage: 'blocked',
  metadata: {
    stage: 'blocked',
    confidence_mode: 'Blocked',
    human_gate_required: true,
    human_gate_reasons: decision.human_gate_reasons || [],
    reasoning: decision.reasoning || 'Pipeline blocked — complete the onboarding form and retry.'
  }
});
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', d._secret).update(body).digest('hex');
return { json: { ...d, _stage_url: d._base + '/api/processing/stage', _stage_body: body, _stage_headers: { 'content-type': 'application/json', 'x-n8n-signature': sig, 'x-n8n-request-id': reqId, 'x-n8n-timestamp': ts } } };

// Sign /api/extraction/source-records — replaces the Supabase LOAD node
// (Gap 4). n8n now needs ZERO DB credentials.
const crypto = require('crypto');
const d = $('Parse CEO result').first().json;
const body = JSON.stringify({ brand_id: d.brand_id });
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', d._secret).update(body).digest('hex');
return { json: { ...d, _src_url: d._base + '/api/extraction/source-records', _src_body: body, _src_headers: {
  'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts
}}};

// Consolidate extractions — GAP 1 + GAP 3 fix.
// • Reads the API response (which already returns the consolidated shape
//   from migration 0028's `normalised` column with legacy fallbacks).
// • Detects PRE-LAUNCH brands: 0 sources from any lane → flag so COO
//   uses form-only Vulnerability-Method default and skips scrape inference.
const api = $input.first().json;
const extractions = api.extractions || { instagram: null, website: null, places: null };
const raw = api.raw || { instagram: null, website: null, places: null };
const sourcesCount = api.sources_count || 0;
const d = $('Parse CEO result').first().json;
const review = (d.form_payload && d.form_payload.review) || {};
const hasFormSignal = !!(review.brand_differentiator || review.arabic_dialect || review.intent_state);
// Pre-launch = no scraped sources AND we have form signal to fall back on.
const isPreLaunch = sourcesCount === 0 && hasFormSignal;
return { json: {
  ...d,
  ceo_decision: d.decision,
  extractions,
  raw_extractions: raw,
  sources_count: sourcesCount,
  is_pre_launch: isPreLaunch,
  data_richness: sourcesCount === 0 ? 'form_only' : sourcesCount === 1 ? 'single_source' : sourcesCount === 2 ? 'partial' : 'rich',
}};

// GAP 5 — stage scraping_complete BEFORE the snapshot write.
const crypto = require('crypto');
const d = $json;
const body = JSON.stringify({
  brand_id: d.brand_id,
  stage: 'scraping_complete',
  metadata: {
    sources_count: d.sources_count,
    data_richness: d.data_richness,
    is_pre_launch: d.is_pre_launch,
    has_instagram: !!d.extractions.instagram,
    has_website: !!d.extractions.website,
    has_places: !!d.extractions.places,
  },
});
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', d._secret).update(body).digest('hex');
return { json: { ...d, _stage_url: d._base + '/api/processing/stage', _stage_body: body, _stage_headers: {
  'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts
}}};

// Build COO build-branddna body.
// GAP 2 — explicitly request three-axis inference + method profile so
// COO Pass 3 produces archetype_primary / lifecycle_stage / intent_state
// AND a method composition (per Three-Axis Framework v2 §Composition Matrix).
// GAP 3 — pre-launch brands tell COO to default to Vulnerability Method
// and skip scrape-derived inference (form-only).
// NOTE: $json here is the stage-emit API response (no _secret/_base/etc),
// so we pull state from Verify HMAC + Consolidate extractions explicitly.
const d = $('Consolidate extractions').first().json;
const v = $('Verify HMAC + parse').first().json;
const review = (d.form_payload && d.form_payload.review) || {};
return { json: {
  ...d,
  _secret: v._secret,
  _base:   v._base,
  body: {
    flow_id: 'N8N-A03',
    brand_id: d.brand_id,
    payload: {
      form_answers:                d.form_payload,
      instagram_extraction:        d.extractions.instagram,
      website_extraction:          d.extractions.website,
      google_business_extraction:  d.extractions.places,
      raw_instagram:               d.raw_extractions?.instagram ?? null,
      request_axes: {
        archetype_primary:    true,
        archetype_secondary:  true,
        lifecycle_stage:      true,
        intent_state:         true,
      },
      method_profile_request: {
        compose: true,
        default_method: d.is_pre_launch ? 'Vulnerability' : null,
        score_threshold: 80,
      },
      data_richness:    d.data_richness,
      is_pre_launch:    d.is_pre_launch,
      form_dialect:     review.arabic_dialect ?? null,
      // GAP 9 — thread the Three-Axis Framework v2 form priors so COO
      // can anchor axis_inference + method composition on user-stated
      // values, not just scraped evidence. All optional/nullable.
      form_priors: {
        archetype_primary:        review.archetype_primary ?? null,
        lifecycle_stage:          review.lifecycle_stage ?? null,
        intent_state:             review.intent_state ?? null,
        primary_kpi_type:         review.primary_kpi_type ?? null,
        primary_channel:          review.primary_channel ?? null,
        bilingual_ratio:          review.bilingual_ratio ?? null,
        formality_level:          review.formality_level ?? null,
        humor_tolerance:          review.humor_tolerance ?? null,
        religious_sensitivity:    review.religious_sensitivity ?? null,
        ramadan_relevance:        review.ramadan_relevance ?? null,
        tone_anti_attribute_ids:  review.tone_anti_attribute_ids ?? null,
        price_position:           review.price_position ?? null,
        brand_differentiator:     review.brand_differentiator ?? null,
      },
    },
  },
}};

const crypto = require('crypto');
const d = $json;
const body = JSON.stringify(d.body);
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', d._secret).update(body).digest('hex');
return { json: { ...d, _coo_url: d._base + '/api/agents/coo/build-branddna', _coo_body: body, _coo_headers: {
  'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts
}}};

// GAP 5 — stage coo_branddna_built BEFORE memory drain.
const crypto = require('crypto');
const d = $('Build COO body').first().json;
const cooResult = $input.first().json.result || $input.first().json;
const body = JSON.stringify({
  brand_id: d.brand_id,
  stage: 'coo_branddna_built',
  metadata: {
    completeness_score:  cooResult.completeness_score ?? null,
    dialect_confirmed:   cooResult.dialect_confirmed ?? false,
    field_nominations:   (cooResult.field_nominations || []).length,
    method_profile:      cooResult.method_profile?.method_name ?? null,
    archetype_primary:   cooResult.axis_inference?.archetype_primary ?? null,
    lifecycle_stage:     cooResult.axis_inference?.lifecycle_stage ?? null,
    intent_state:        cooResult.axis_inference?.intent_state ?? null,
  },
});
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', d._secret).update(body).digest('hex');
return { json: { ...d, _coo_full_result: cooResult, _stage_url: d._base + '/api/processing/stage', _stage_body: body, _stage_headers: {
  'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts
}}};

// GAP 3 — Doc §5.3 step 5: SECOND CEO call (confidence gate / refinement).
// First CEO call (step 1) routed with no evidence. Now COO has produced
// real field_nominations + axis_inference, so CEO can re-classify with
// actual evidence_bundle_states and upgrade/downgrade confidence_mode.
const crypto = require('crypto');
const v = $('Verify HMAC + parse').first().json;
const coo = $('Sign · stage coo_branddna_built').first().json._coo_full_result || {};
// Build evidence_bundle_states map: field_path → confidence_state.
const evidence = {};
for (const n of (coo.field_nominations || [])) {
  if (n && n.field_path && n.confidence_state) {
    evidence[n.field_path] = n.confidence_state;
  }
}
const body = JSON.stringify({
  flow_id: 'N8N-A03',
  brand_id: v.brand_id,
  payload: {
    request_type: 'onboarding_new',
    trigger_payload: {
      slug: v.slug,
      pass: 'confidence_gate_post_coo',
      coo_completeness:    coo.completeness_score ?? null,
      coo_dialect_confirmed: !!coo.dialect_confirmed,
      method_recommended:  coo.method_profile?.method_name ?? null,
      archetype_primary:   coo.axis_inference?.archetype_primary ?? null,
      lifecycle_stage:     coo.axis_inference?.lifecycle_stage ?? null,
      intent_state:        coo.axis_inference?.intent_state ?? null,
    },
    evidence_bundle_states: evidence,
    occasion_flags: ['none'],
    current_month_spend_usd: 0,
    monthly_ceiling_usd: 50,
  },
});
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', v._secret).update(body).digest('hex');
return { json: {
  brand_id: v.brand_id,
  _secret: v._secret, _base: v._base,
  _gate_url: v._base + '/api/agents/ceo/classify',
  _gate_body: body,
  _gate_headers: {
    'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts,
  },
}};

// GAP 10 — emit a visible stage transition between the second CEO call
// and the Memory Controller drain, so the live tracker doesn't jump from
// coo_branddna_built straight to memory_drained.
const crypto = require('crypto');
const v = $('Verify HMAC + parse').first().json;
const gateResp = $input.first().json || {};
const decision = gateResp?.result?.decision || gateResp?.decision || {};
const body = JSON.stringify({
  brand_id: v.brand_id,
  stage: 'ceo_confidence_refined',
  metadata: {
    confidence_mode:     decision.confidence_mode ?? null,
    human_gate_required: !!decision.human_gate_required,
    human_gate_reasons:  decision.human_gate_reasons ?? [],
    pipeline_assigned:   decision.pipeline_assigned ?? null,
    gate_ok:             !!(gateResp?.ok ?? false),
  },
});
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', v._secret).update(body).digest('hex');
return { json: { brand_id: v.brand_id, _secret: v._secret, _base: v._base, _stage_url: v._base + '/api/processing/stage', _stage_body: body, _stage_headers: {
  'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts
}}};

// $json here is the stage-emit API response — no _secret. Pull from Verify HMAC.
const crypto = require('crypto');
const v = $('Verify HMAC + parse').first().json;
const memBody = { flow_id: 'N8N-A03', batch_size: 100 };
const innerBody = JSON.stringify(memBody);
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', v._secret).update(innerBody).digest('hex');
return { json: {
  brand_id: v.brand_id,
  _secret: v._secret, _base: v._base,
  _mem_url: v._base + '/api/memory/process',
  _mem_body: innerBody,
  _mem_headers: {
    'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts,
  },
}};

// GAP 5 — stage memory_drained BEFORE qdrant + final snapshot.
const crypto = require('crypto');
const d = $('Sign · Memory process').first().json;
const memResult = $input.first().json.result || $input.first().json;
const body = JSON.stringify({ brand_id: d.brand_id, stage: 'memory_drained', metadata: { written: memResult.written ?? 0, rejected: memResult.rejected ?? 0 } });
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', d._secret).update(body).digest('hex');
return { json: { ...d, _mem_full_result: memResult, _stage_url: d._base + '/api/processing/stage', _stage_body: body, _stage_headers: {
  'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts
}}};

// Sign /api/vectors/setup body. Best-effort — Qdrant failure is non-fatal.
// $json here is the stage-emit API response — pull state from Verify HMAC.
const crypto = require('crypto');
const v = $('Verify HMAC + parse').first().json;
const body = JSON.stringify({ brand_id: v.brand_id, flow_id: 'N8N-A03' });
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', v._secret).update(body).digest('hex');
return { json: {
  brand_id: v.brand_id,
  _secret: v._secret, _base: v._base,
  _q_url: v._base + '/api/vectors/setup',
  _q_body: body,
  _q_headers: {
    'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts,
  },
}};

// Build the FULL final snapshot.
// GAP 4 — emit via /api/processing/stage with mark_complete=true. Replaces 2
// Supabase nodes. GAP 6 — lenient dialect_confirmed (COO explicit OR form
// dialect + axis_inference present). GAP 3 — refined confidence_mode from
// the SECOND CEO call (post-COO confidence gate). GAP 7 — surface
// archetype_secondary so A01 sees the composition pair. GAP 8 — validate
// method_name against the 6 framework methods (Three-Axis v2).
const crypto = require('crypto');
const d = $('Build COO body').first().json;
const coo = $('Sign · stage coo_branddna_built').first().json._coo_full_result || {};
const memory = $('Sign · stage memory_drained').first().json._mem_full_result || {};
const consolidated = $('Consolidate extractions').first().json;
const extractions = consolidated.extractions;
const review = (d.form_payload && d.form_payload.review) || {};
const dialectConfirmed = !!coo.dialect_confirmed || !!(review.arabic_dialect && coo.axis_inference?.lifecycle_stage);
// GAP 8 — Three-Axis Framework v2: the only 6 valid method names.
const VALID_METHODS = ['Authenticity','Heritage','Metaphor','Paradox','Diagnostic','Vulnerability'];
const rawMethodName = coo.method_profile?.method_name ?? null;
const methodValid = !!rawMethodName && VALID_METHODS.includes(rawMethodName);
if (rawMethodName && !methodValid) {
  console.warn('[A03] method_name out of framework set:', rawMethodName);
}
// Pull refined confidence_mode from the post-COO confidence gate when present.
// If the gate failed (neverError swallows it), fall back to the first CEO
// classify result which is always available.
let refinedDecision = null;
try {
  const gateResp = $('POST · CEO confidence gate').first().json;
  refinedDecision = gateResp?.result?.decision || gateResp?.decision || null;
} catch (_) { /* gate node never ran — keep first CEO decision */ }
const firstDecision = $('Parse CEO result').first().json.decision || {};
const confidenceMode = refinedDecision?.confidence_mode || firstDecision.confidence_mode || 'Cautious';
const snapshotData = {
  stage: 'snapshot_ready',
  completeness:            coo.completeness_score ?? 70,
  dialect_confirmed:       dialectConfirmed,
  field_nominations_total: (coo.field_nominations || []).length,
  memory_written:          memory.written ?? 0,
  memory_rejected:         memory.rejected ?? 0,
  extractions,
  axis_inference:          coo.axis_inference ?? null,
  // GAP 7 — pair surfaces so A01 / downstream can do composition lookups.
  archetype_primary:       coo.axis_inference?.archetype_primary ?? null,
  archetype_secondary:     coo.axis_inference?.archetype_secondary ?? null,
  lifecycle_stage:         coo.axis_inference?.lifecycle_stage ?? null,
  intent_state:            coo.axis_inference?.intent_state ?? null,
  method_profile:          coo.method_profile ?? null,
  method_name:             methodValid ? rawMethodName : null,
  method_valid:            methodValid,
  coo_reasoning:           coo.reasoning ?? null,
  // GAP 5 — pre-launch flag rides the snapshot so the A01 readiness IF
  // can short-circuit (no scraped content → no calendar evidence).
  is_pre_launch:           !!consolidated.is_pre_launch,
  data_richness:           consolidated.data_richness ?? null,
  // GAP 3 — refined CEO verdict (vs the initial pre-COO routing).
  confidence_mode:         confidenceMode,
  confidence_refined:      !!refinedDecision,
  human_gate_required:     !!(refinedDecision || firstDecision).human_gate_required,
  human_gate_reasons:      (refinedDecision || firstDecision).human_gate_reasons || [],
};
const body = JSON.stringify({
  brand_id: d.brand_id,
  stage: 'snapshot_ready',
  metadata: snapshotData,
  mark_complete: true,
