const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', d._secret).update(body).digest('hex');
return { json: { ...d, _snapshot_data: snapshotData, _stage_url: d._base + '/api/processing/stage', _stage_body: body, _stage_headers: {
  'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts
}}};

// Status callback to /api/webhooks/n8n.
const crypto = require('crypto');
const d = $('Build + sign final snapshot').first().json;
const snap = d._snapshot_data;
const innerBody = JSON.stringify({
  event_type: 'onboarding_complete',
  flow_id: 'N8N-A03',
  brand_id: d.brand_id,
  payload: {
    completeness_score: snap.completeness,
    dialect_confirmed: snap.dialect_confirmed,
    memory_written: snap.memory_written,
