// GAP 2 — Doc §5.3 step 9. Emitted when completeness_score < 40 OR
// dialect_unconfirmed. Builds 3 gap questions for the user from the COO's
// `critical_fields_missing` array (or, if absent, derives from
// field_nominations confidence_state). UI reads brand_snapshots.snapshot_data.
// .gap_questions[] and asks the user to fill them in.
const crypto = require('crypto');
const v = $('Verify HMAC + parse').first().json;
const snap = $('Build + sign final snapshot').first().json._snapshot_data || {};
const coo = $('Sign · stage coo_branddna_built').first().json._coo_full_result || {};
// Prefer COO's explicit critical_fields_missing; fall back to deriving from
// field_nominations (any with confidence < inferred_medium).
let missing = Array.isArray(coo.critical_fields_missing) ? coo.critical_fields_missing.slice() : [];
if (missing.length === 0) {
  for (const n of (coo.field_nominations || [])) {
    if (n && (n.confidence_state === 'inferred_low' || n.confidence_state === 'rejected' || !n.confidence_state)) {
      missing.push(n.field_path);
    }
  }
}
// Field-name → human-friendly question. Doc-anchored vocab.
const QUESTIONS = {
  arabic_dialect:           'Which Arabic dialect best matches your brand voice — Najdi, Hejazi, Gulf, MSA accessible, MSA formal, or Mixed?',
  brand_differentiator:     'In one or two sentences, what makes this brand distinctive vs. competitors?',
  primary_color_hex:        'What is your primary brand color (hex code)?',
  archetype_primary:        'Which Jungian archetype best fits this brand — Hero, Sage, Lover, Outlaw, Caregiver, Magician, Explorer, Innocent, Jester, Everyman, Ruler, or Creator?',
  lifecycle_stage:          'Where is this brand in its lifecycle — pre_launch, launch, growth, maturity, or recovery?',
  intent_state:             'What is your primary intent this month — launch, grow, defend, harvest, or recover?',
  primary_kpi_type:         'What is the primary KPI you optimise for — engagement, conversion, awareness, or trust?',
  religious_sensitivity:    'How religiously sensitive should the brand voice be — Low, Medium, or High?',
  bilingual_ratio:          'What Arabic-vs-English ratio fits — arabic_only, arabic_primary, balanced, or english_primary?',
  formality_level:          'Pick the formality level — casual, semi_formal, or formal.',
  humor_tolerance:          'Pick the humor tolerance — none, light, or moderate.',
  tone_anti_attribute_ids:  'Which tones should this brand NEVER sound like? (pick from: aggressive, salesy, flashy, edgy, ironic, formal_corporate, casual_humor, western_casual)',
  ramadan_relevance:        'How relevant is Ramadan to your campaigns — Critical, High, Medium, Low, or Not_relevant?',
  primary_channel:          'Which platform is your primary channel — Instagram, Snapchat, TikTok, or Twitter?',
};
// Map raw field paths (which may include namespaces) to base names.
const seen = new Set();
const topThree = [];
for (const fp of missing) {
  const base = String(fp).split('.').pop();
  if (!base || seen.has(base)) continue;
  seen.add(base);
  if (QUESTIONS[base]) {
    topThree.push({ field: base, question: QUESTIONS[base] });
    if (topThree.length === 3) break;
  }
}
// If COO didn't surface anything but the gate failed (e.g. dialect_unconfirmed
// with no field_nominations populated), seed at least the dialect question
// so the user has something to act on.
if (topThree.length === 0 && !snap.dialect_confirmed) {
  topThree.push({ field: 'arabic_dialect', question: QUESTIONS.arabic_dialect });
}
// Suppression: if the form is complete (no real gaps), use a self-resolving
// stage emission instead of a user-facing gap. /api/processing/stage with
// stage='gap_notification' + metadata.gap_questions=[] is treated as a benign
// audit row by the UI (no banner shown). Better than failing the HTTP node.
const metadata = topThree.length === 0
  ? { reason: 'suppressed_no_gaps', completeness: snap.completeness ?? 0, dialect_confirmed: !!snap.dialect_confirmed, gap_questions: [], human_gate_reasons: snap.human_gate_reasons || [], suppressed: true }
  : {
  reason: snap.completeness < 40 ? 'low_completeness' : 'dialect_unconfirmed',
  completeness: snap.completeness ?? 0,
  dialect_confirmed: !!snap.dialect_confirmed,
  gap_questions: topThree,
  human_gate_reasons: snap.human_gate_reasons || [],
};
const body = JSON.stringify({
  brand_id: v.brand_id,
  stage: 'gap_notification',
  metadata,
});
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', v._secret).update(body).digest('hex');
return { json: {
  brand_id: v.brand_id,
  _secret: v._secret, _base: v._base,
  _stage_url: v._base + '/api/processing/stage',
  _stage_body: body,
  _stage_headers: {
    'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts,
  },
}};
